        <el-table-column align="center" fixed="right" label="操作" width="160">
          <template #default="scope">
            <el-button link type="primary" @click="openDetail(scope.row.id)">查看</el-button>
            <el-button link type="primary" @click="openForm('update', scope.row.id)">编辑</el-button>
            <el-button link type="danger" @click="handleDelete(scope.row.id)">删除</el-button>
          </template>
        </el-table-column>
    </el-table>
    <Pagination v-model:limit="queryParams.pageSize" v-model:page="queryParams.pageNo" :total="total" @pagination="getList" />
  </ContentWrap>

  <BoxunRawMaterialLedgerForm ref="formRef" @success="getList" />
  <BoxunRawMaterialLedgerDetail ref="detailRef" />
</template>

<script setup lang="ts">
import { dateFormatter } from '@/utils/formatTime'
import request from '@/config/axios'
import download from '@/utils/download'
import * as BoxunRawMaterialLedgerApi from './BoxunRawMaterialLedgerApi'
import BoxunRawMaterialLedgerForm from './BoxunRawMaterialLedgerForm.vue'
import BoxunRawMaterialLedgerDetail from './BoxunRawMaterialLedgerDetail.vue'

type BoxunRawMaterialLedgerRow = Awaited<ReturnType<typeof BoxunRawMaterialLedgerApi.getBoxunRawMaterialLedgerPage>>['list'][number]
type EntityId = string | number

defineOptions({ name: 'BoxunRawMaterialLedger' })

const message = useMessage()
const { t } = useI18n()
const loading = ref(false)
const total = ref(0)
const rows = ref<BoxunRawMaterialLedgerRow[]>([])
const queryFormRef = ref()
const queryParams = reactive({
  pageNo: 1,
  pageSize: 10,
  strengthGrade: '',
  manufacturer: '',
  furnaceBatchNumber: '',
  buildingNo: '',
  concatPosition: '',
  representativeBatch: '',
  numberOfPieces: '',
  batchNumber: '',
  remarks: '',
  testNumber: ''
})



const getList = async () => {
  loading.value = true
  try {
    const data = await BoxunRawMaterialLedgerApi.getBoxunRawMaterialLedgerPage(queryParams)
    rows.value = data.list
    total.value = Number(data.total)
  } finally {
    loading.value = false
  }
}

const handleQuery = () => {
  queryParams.pageNo = 1
  getList()
}

const resetQuery = () => {

  queryFormRef.value?.resetFields()

  handleQuery()
}

const formRef = ref()
const openForm = (type: 'create' | 'update', id?: EntityId) => {
  formRef.value?.open(type, id, type === 'create' ? undefined : undefined)
}


const detailRef = ref()
const openDetail = (id: EntityId) => {
  detailRef.value?.open(id)
}



const handleDelete = async (id?: EntityId) => {
  if (id === undefined) return
  await message.delConfirm()
  await BoxunRawMaterialLedgerApi.deleteBoxunRawMaterialLedger(id)
  message.success(t('common.delSuccess'))
  await getList()
}

const checkedIds = ref<EntityId[]>([])
const handleSelectionChange = (rows: BoxunRawMaterialLedgerRow[]) => {
  checkedIds.value = rows.map((row) => row.id).filter((id): id is EntityId => id !== undefined)
}

const handleDeleteBatch = async () => {
  await message.delConfirm()
  await BoxunRawMaterialLedgerApi.deleteBoxunRawMaterialLedgerList(checkedIds.value)
  message.success(t('common.delSuccess'))
  checkedIds.value = []
  await getList()
}
const exportLoading = ref(false)
const handleExport = async () => {
  await message.exportConfirm()
  exportLoading.value = true
  try {
    const data = await request.download({ url: '/boxun/raw-material-ledger/export-excel', params: queryParams })
    download.excel(data, 'boxunRawMaterialLedger.xls')
  } finally {
    exportLoading.value = false
  }
}

onMounted(getList)
</script>
